begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.c() returns uuid language sql immutable as $$select '00000000-0000-0000-0000-000000000111'::uuid$$;
create function pg_temp.sid() returns uuid language sql stable as $$select current_setting('phase5a.sid')::uuid$$;
create function pg_temp.close_session(counted bigint default 16000, expected numeric default 15000, key uuid default '5a000000-0000-4000-8000-000000000001') returns jsonb language sql as $$
 select public.cafeteria_operations_close(pg_temp.c(),pg_temp.sid(),1,counted,'administrative_recovery','Synthetic close',key,expected)$$;
create function pg_temp.sale(key text,tender text default 'cash',identified boolean default false) returns jsonb language sql as $$
 select public.checkout_purchase(jsonb_build_object('request_key',key,'register_session_id',pg_temp.sid(),
 'cafeteria_customer_id',case when tender='cash' and not identified then null else '00000000-0000-0000-0000-000000006901' end,
 'items',jsonb_build_array(jsonb_build_object('product_id','00000000-0000-0000-0000-000000008101','quantity',1,'expected_product_version',1,'expected_unit_price_minor','5000')),
 'expected_total_minor','5000','tender',case when tender='cash' then jsonb_build_object('type','cash','cash_received_minor','10000') else jsonb_build_object('type',tender) end))$$;
select ok(not has_table_privilege('authenticated','pikas_private.register_close_reconciliations','select'),'Close snapshot private');
select ok(not has_function_privilege('anon','public.cafeteria_operations_read(uuid,text,integer,uuid)','execute'),'Anonymous denied');
select ok(not has_function_privilege('service_role','public.cafeteria_operations_close(uuid,uuid,integer,bigint,text,text,uuid,numeric)','execute'),'No service financial bypass');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002002',true);set local role authenticated;
select public.post_manual_wallet_replenishment('00000000-0000-0000-0000-000000007001',10000,'phase5a-wallet-fixture-0001','Synthetic fixture','Verified fictional amount',null);
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002008',true);set local role authenticated;
select lives_ok($$select public.open_register_session('00000000-0000-0000-0000-000000009401','00000000-0000-0000-0000-000000009501',10000,'phase5a-open-00000001')$$,'Cashier opens assigned session');
select set_config('phase5a.sid',(select session_id::text from public.get_my_open_register_session()),true);
select throws_ok($$select public.cafeteria_operations_read(pg_temp.c(),'transactions')$$,'42501',null,'Cashier has no admin history');
select lives_ok($$select pg_temp.sale('phase5a-anonymous-000001')$$,'No Usuario cash committed');
select lives_ok($$select pg_temp.sale('phase5a-wallet-00000001','student_wallet')$$,'Wallet committed');
set constraints all immediate;set constraints all deferred;
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002003',true);set local role authenticated;
select is(jsonb_array_length(public.cafeteria_operations_read(pg_temp.c(),'transactions')->'data'),2,'Both sales in authoritative history');
select is(public.cafeteria_operations_read(pg_temp.c(),'session',0,pg_temp.sid())->'data'->'summary'->>'expected_minor','15000','Opening + net cash sale; wallet excluded');
select is(public.cafeteria_operations_read(pg_temp.c(),'session',0,pg_temp.sid())->'data'->'summary'->>'purchase_count','2','Both tenders counted');
select set_config('phase5a.purchase',(public.cafeteria_operations_read(pg_temp.c(),'transactions')->'data'->0->>'id'),true);
select is(public.cafeteria_operations_read(pg_temp.c(),'transaction',0,current_setting('phase5a.purchase')::uuid)->'data'->'items'->0->>'name','Agua mineral','Historical purchased item snapshot');
select is(public.cafeteria_operations_read(pg_temp.c(),'transaction',0,current_setting('phase5a.purchase')::uuid)->'data'->>'total_minor','5000','Committed receipt total');
select is(public.cafeteria_operations_read(pg_temp.c(),'transaction',0,current_setting('phase5a.purchase')::uuid)->'data'->>'session_id',pg_temp.sid()::text,'Detail retains exact session');
select is(jsonb_array_length(public.cafeteria_operations_read(pg_temp.c(),'transactions',25)->'data'),0,'Bounded next page empty');
select throws_ok($$select public.cafeteria_operations_read(pg_temp.c(),'transaction',0,'5a000000-0000-4000-8000-999999999999')$$,'42501',null,'Unknown detail fails closed');
select throws_ok($$select public.cafeteria_operations_read('b9496342-5079-46ae-83b8-05c39bcbd7fe','sessions')$$,'42501',null,'Customer admin cannot read sandbox history');
select throws_ok($$select public.cafeteria_operations_read('00000000-0000-0000-0000-000000000211','transactions')$$,'42501',null,'Other tenant denied');
select throws_ok($$select public.cafeteria_operations_read('00000000-0000-0000-0000-000000000112','sessions')$$,'42501',null,'Other cafeteria denied');
select throws_ok($$select pg_temp.close_session(16000,10000)$$,'40001','stale_expected_cash','Stale preview rejected under lock');
select throws_ok($$select pg_temp.close_session(-1)$$,'22023',null,'Negative count denied');
select lives_ok($$select pg_temp.close_session()$$,'Admin explicit recovery closes');
select is(pg_temp.close_session()->'session'->>'status','closed','Exact retry returns permanent close');
select is(pg_temp.close_session()->'session'->>'difference_minor','1000','Positive difference is counted minus expected');
select is(pg_temp.close_session()->'session'->>'close_snapshot','true','New close captures immutable expected');
select throws_ok($$select pg_temp.close_session(15000)$$,'23505','request_key_reused','Changed retry count rejected');
select throws_ok($$select pg_temp.close_session(16000,14000)$$,'23505','request_key_reused','Changed retry expected rejected');
select throws_ok($$select pg_temp.close_session(16000,15000,'5a000000-0000-4000-8000-000000000002')$$,'23505',null,'Different close denied');
reset role;
select is((select summary->>'expected_minor' from pikas_private.register_close_reconciliations where session_id=pg_temp.sid()),'15000','Captured expected stored once');
select throws_ok($$delete from pikas_private.register_close_reconciliations where session_id=pg_temp.sid()$$,'23514',null,'Snapshot cannot be deleted');
update public.cafeteria_memberships set status='suspended' where person_id='00000000-0000-0000-0000-000000001003';
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002003',true);set local role authenticated;
select throws_ok($$select public.cafeteria_operations_read(pg_temp.c(),'sessions')$$,'42501',null,'Suspended admin denied read');
select throws_ok($$select pg_temp.close_session()$$,'42501',null,'Revoked admin cannot recover success');
reset role;update public.cafeteria_memberships set status='active' where person_id='00000000-0000-0000-0000-000000001003';
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002008',true);set local role authenticated;
select is((select count(*) from public.get_my_open_register_session()),0::bigint,'POS has no open session; no replacement created');
select throws_ok($$select pg_temp.sale('phase5a-after-close-0001')$$,'23514','SESSION_CLOSED','Closed session rejects sale');
select lives_ok($$select public.open_register_session('00000000-0000-0000-0000-000000009401','00000000-0000-0000-0000-000000009501',10000,'phase5a-open-00000002')$$,'New explicit opening supported');
select set_config('phase5a.sid',(select session_id::text from public.get_my_open_register_session()),true);
select lives_ok($$select public.close_my_register_session(pg_temp.sid(),1,9000,'phase5a-own-close-0001')$$,'Existing own close preserved');
reset role;
select is((select difference_minor::text from pikas_private.register_close_reconciliations where session_id=pg_temp.sid()),'-1000','Negative difference captured for own close');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002008',true);set local role authenticated;
select public.open_register_session('00000000-0000-0000-0000-000000009401','00000000-0000-0000-0000-000000009501',0,'phase5a-open-00000003');
select set_config('phase5a.sid',(select session_id::text from public.get_my_open_register_session()),true);
select public.close_my_register_session(pg_temp.sid(),1,0,'phase5a-own-close-0002');reset role;
select is((select difference_minor::text from pikas_private.register_close_reconciliations where session_id=pg_temp.sid()),'0','Zero difference captured');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002003',true);set local role authenticated;
select public.configure_cafeteria_refund_policy(pg_temp.c(),1,false,0);reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002008',true);set local role authenticated;
select public.open_register_session('00000000-0000-0000-0000-000000009401','00000000-0000-0000-0000-000000009501',10000,'phase5a-open-refund-001');
select set_config('phase5a.sid',(select session_id::text from public.get_my_open_register_session()),true);
select set_config('phase5a.refund_purchase',(pg_temp.sale('phase5a-cash-refund-sale1','cash',true)->>'purchase_id'),true);
select lives_ok($$select public.create_purchase_refund(current_setting('phase5a.refund_purchase')::uuid,'5000','error',null,'phase5a-refund-source-01','00000000-0000-0000-0000-000000004601',pg_temp.sid())$$,'Existing cash refund uses authoritative session outflow');
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002003',true);set local role authenticated;
select is(public.cafeteria_operations_read(pg_temp.c(),'session',0,pg_temp.sid())->'data'->'summary'->>'expected_minor','10000','Refund subtracts actual outflow, not original cash received');
select is(public.cafeteria_operations_read(pg_temp.c(),'session',0,pg_temp.sid())->'data'->'summary'->>'cash_refunds_minor','5000','Refund is separately visible');
select is(jsonb_array_length(public.cafeteria_operations_read(pg_temp.c(),'session',0,pg_temp.sid())->'data'->'cash_movements'),1,'Cash movement explains difference from gross sales');
select lives_ok($$select pg_temp.close_session(10000,10000,'5a000000-0000-4000-8000-000000000004')$$,'Close captures refund-inclusive expected');
reset role;
insert into public.staff_campus_affiliations(account_id,school_id,staff_affiliation_id,school_location_id)
values('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000006501','00000000-0000-0000-0000-000000000211');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002002',true);set local role authenticated;
select set_config('phase5a.receivable',public.configure_staff_receivable_account('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000006501',0,false,null,'phase5a-staff-create-01')->>'account_id',true);
select public.configure_staff_receivable_account('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000006501',1,true,'5000','phase5a-staff-enable-01');reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002011',true);set local role authenticated;
select public.open_register_session('00000000-0000-0000-0000-000000009401','00000000-0000-0000-0000-000000009503',10000,'phase5a-staff-open-0001');
select set_config('phase5a.sid',(select session_id::text from public.get_my_open_register_session()),true);
select set_config('phase5a.credit_purchase',public.checkout_purchase(jsonb_build_object('request_key','phase5a-staff-credit-sale1','register_session_id',pg_temp.sid(),'cafeteria_customer_id','00000000-0000-0000-0000-000000006902','expected_total_minor','5000','items',jsonb_build_array(jsonb_build_object('product_id','00000000-0000-0000-0000-000000008101','quantity',1,'expected_product_version',1,'expected_unit_price_minor','5000')),'tender',jsonb_build_object('type','staff_credit')))->>'purchase_id',true);
select lives_ok($$select public.settle_staff_receivable(current_setting('phase5a.receivable')::uuid,'500','cash','00000000-0000-0000-0000-000000000111','00000000-0000-0000-0000-000000004603',pg_temp.sid(),'Synthetic cash collection',null,'phase5a-staff-collection1')$$,'Existing cash collection belongs to supervisor session');
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002003',true);set local role authenticated;
select is(public.cafeteria_operations_read(pg_temp.c(),'session',0,pg_temp.sid())->'data'->'summary'->>'expected_minor','10500','Staff credit excluded, cash collection included');
select is(public.cafeteria_operations_read(pg_temp.c(),'session',0,pg_temp.sid())->'data'->'summary'->>'cash_settlements_minor','500','Cash collections separately visible');
select is(public.cafeteria_operations_read(pg_temp.c(),'transaction',0,current_setting('phase5a.credit_purchase')::uuid)->'data'->>'tender','staff_credit','Existing staff-credit tender represented truthfully');
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002011',true);set local role authenticated;
select public.close_my_register_session(pg_temp.sid(),1,10500,'phase5a-staff-close-001');reset role;
select is((select summary->>'expected_minor' from pikas_private.register_close_reconciliations where session_id=pg_temp.sid()),'10500','Captured expected includes authoritative cash collections');
set constraints all immediate;
select * from finish();rollback;
